static _R _dragByKeyAndShoot(String method, Map<String, String> params)
    async {
  final keyValue = params['key'];
  if (keyValue == null || keyValue.isEmpty) {
    return _error('key parameter required');
  }
  final dx = double.tryParse(params['dx'] ?? '');
  final dy = double.tryParse(params['dy'] ?? '');
  if (dx == null || dy == null) {
    return _error('dx and dy parameters required (double)');
  }
  final steps = (int.tryParse(params['steps'] ?? '8') ?? 8).clamp(1, 120);
  final holdStep =
      (int.tryParse(params['holdStep'] ?? '') ?? ((steps / 2).ceil()))
          .clamp(1, steps);
  final pixelRatio = double.tryParse(params['pixelRatio'] ?? '') ?? 1.0;

  final kindParam = (params['kind'] ?? '').toLowerCase();
  final pointerKind = switch (kindParam) {
    'touch' => PointerDeviceKind.touch,
    'mouse' => PointerDeviceKind.mouse,
    _ => (defaultTargetPlatform == TargetPlatform.macOS ||
            defaultTargetPlatform == TargetPlatform.linux ||
            defaultTargetPlatform == TargetPlatform.windows)
        ? PointerDeviceKind.mouse
        : PointerDeviceKind.touch,
  };

  final element = _findElementByKey(keyValue);
  if (element == null) {
    return _error('no widget found with key "$keyValue"');
  }

  final ro = element.findRenderObject();
  if (ro is! RenderBox || !ro.attached || !ro.hasSize || ro.size.isEmpty) {
    return _error('widget with key "$keyValue" has no usable RenderBox');
  }

  Future<Map<String, Object?>> capture() async {
    final renderObject = DebugHooks.screenshotBoundaryKey.currentContext
        ?.findRenderObject();
    if (renderObject is! RenderRepaintBoundary) {
      return {
        'captured': false,
        'error': 'screenshot boundary not mounted yet',
      };
    }
    final image = await renderObject.toImage(pixelRatio: pixelRatio);
    final png = await image.toByteData(format: ui.ImageByteFormat.png);
    final width = image.width;
    final height = image.height;
    image.dispose();
    if (png == null) {
      return {
        'captured': false,
        'error': 'toByteData returned null',
      };
    }
    return {
      'captured': true,
      'png_base64': base64Encode(png.buffer.asUint8List()),
      'width': width,
      'height': height,
    };
  }

  // Force synthetic pointer sequence so we can capture mid-gesture.
  final binding = GestureBinding.instance;
  final start = ro.localToGlobal(ro.size.center(Offset.zero));

  _syntheticPointerSeq++;
  final pointer = 0x70000 | (_syntheticPointerSeq & 0xFFFF);
  final t0 = Duration(milliseconds: DateTime.now().millisecondsSinceEpoch);

  binding.handlePointerEvent(
    PointerAddedEvent(
      pointer: pointer,
      position: start,
      kind: pointerKind,
      timeStamp: t0,
    ),
  );
  binding.handlePointerEvent(
    PointerDownEvent(
      pointer: pointer,
      position: start,
      kind: pointerKind,
      buttons: kPrimaryButton,
      timeStamp: t0,
    ),
  );

  Map<String, Object?> during = const {};

  for (var i = 1; i <= steps; i++) {
    final p = Offset(
      start.dx + (dx * i / steps),
      start.dy + (dy * i / steps),
    );
    final ts = t0 + Duration(milliseconds: 8 * i);
    binding.handlePointerEvent(
      PointerMoveEvent(
        pointer: pointer,
        position: p,
        kind: pointerKind,
        buttons: kPrimaryButton,
        timeStamp: ts,
      ),
    );

    if (i == holdStep) {
      await Future<void>.delayed(const Duration(milliseconds: 50));
      during = await capture();
    }
  }

  final end = Offset(start.dx + dx, start.dy + dy);
  final tEnd = t0 + Duration(milliseconds: 8 * (steps + 1));
  binding.handlePointerEvent(
    PointerUpEvent(
      pointer: pointer,
      position: end,
      kind: pointerKind,
      timeStamp: tEnd,
    ),
  );
  binding.handlePointerEvent(
    PointerRemovedEvent(
      pointer: pointer,
      position: end,
      kind: pointerKind,
      timeStamp: tEnd,
    ),
  );

  await Future<void>.delayed(const Duration(milliseconds: 50));
  final post = await capture();

  return _ok({
    'dragged': keyValue,
    'from': {'x': start.dx, 'y': start.dy},
    'to': {'x': end.dx, 'y': end.dy},
    'steps': steps,
    'kind': pointerKind.name,
    'during': during,
    'post': post,
    'holdStep': holdStep,
    'pixelRatio': pixelRatio,
  });
}

